-- Phase 4 follow-up: richer early task events per onboarding (task types, last activity, momentum). READ-ONLY (Dev). Counts and days only.
select o.id as onboarding_id,
  count(*) filter (where tk.type = 'employee_data_completion' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_employee_data_completion_d3,
  count(*) filter (where tk.type = 'employee_data_completion' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_employee_data_completion_d3,
  count(*) filter (where tk.type = 'employee_document_completion' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_employee_document_completion_d3,
  count(*) filter (where tk.type = 'employee_document_completion' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_employee_document_completion_d3,
  count(*) filter (where tk.type = 'employee_contract_sign' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_employee_contract_sign_d3,
  count(*) filter (where tk.type = 'employee_contract_sign' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_employee_contract_sign_d3,
  count(*) filter (where tk.type = 'deposit_invoice' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_deposit_invoice_d3,
  count(*) filter (where tk.type = 'deposit_invoice' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_deposit_invoice_d3,
  count(*) filter (where tk.type = 'payment_verification' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_payment_verification_d3,
  count(*) filter (where tk.type = 'payment_verification' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_payment_verification_d3,
  count(*) filter (where tk.type = 'form' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_form_d3,
  count(*) filter (where tk.type = 'form' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_form_d3,
  count(*) filter (where tk.type = 'worker_management_team' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_worker_management_team_d3,
  count(*) filter (where tk.type = 'worker_management_team' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_worker_management_team_d3,
  count(*) filter (where tk.type = 'associate_employee_documents' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_associate_employee_documents_d3,
  count(*) filter (where tk.type = 'associate_employee_documents' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_associate_employee_documents_d3,
  count(*) filter (where tk.type = 'email_template' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_email_template_d3,
  count(*) filter (where tk.type = 'email_template' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_email_template_d3,
  count(*) filter (where tk.type = 'instructions' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days') as done_instructions_d3,
  count(*) filter (where tk.type = 'instructions' and tk.inserted_at <= o.inserted_at + interval '3 days') as has_instructions_d3,
  max(extract(epoch from (tk.updated_at - o.inserted_at))/86400) filter (where tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days' and tk.updated_at >= o.inserted_at) as last_done_day_d3,
  min(extract(epoch from (tk.updated_at - o.inserted_at))/86400) filter (where tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '3 days' and tk.updated_at >= o.inserted_at) as first_done_day_d3,
  count(*) filter (where tk.status::text = 'completed' and tk.updated_at > o.inserted_at + interval '0 days' and tk.updated_at <= o.inserted_at + interval '3 days') as done_last3_d3,
  count(*) filter (where tk.type = 'employee_data_completion' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_employee_data_completion_d7,
  count(*) filter (where tk.type = 'employee_data_completion' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_employee_data_completion_d7,
  count(*) filter (where tk.type = 'employee_document_completion' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_employee_document_completion_d7,
  count(*) filter (where tk.type = 'employee_document_completion' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_employee_document_completion_d7,
  count(*) filter (where tk.type = 'employee_contract_sign' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_employee_contract_sign_d7,
  count(*) filter (where tk.type = 'employee_contract_sign' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_employee_contract_sign_d7,
  count(*) filter (where tk.type = 'deposit_invoice' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_deposit_invoice_d7,
  count(*) filter (where tk.type = 'deposit_invoice' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_deposit_invoice_d7,
  count(*) filter (where tk.type = 'payment_verification' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_payment_verification_d7,
  count(*) filter (where tk.type = 'payment_verification' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_payment_verification_d7,
  count(*) filter (where tk.type = 'form' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_form_d7,
  count(*) filter (where tk.type = 'form' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_form_d7,
  count(*) filter (where tk.type = 'worker_management_team' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_worker_management_team_d7,
  count(*) filter (where tk.type = 'worker_management_team' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_worker_management_team_d7,
  count(*) filter (where tk.type = 'associate_employee_documents' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_associate_employee_documents_d7,
  count(*) filter (where tk.type = 'associate_employee_documents' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_associate_employee_documents_d7,
  count(*) filter (where tk.type = 'email_template' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_email_template_d7,
  count(*) filter (where tk.type = 'email_template' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_email_template_d7,
  count(*) filter (where tk.type = 'instructions' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days') as done_instructions_d7,
  count(*) filter (where tk.type = 'instructions' and tk.inserted_at <= o.inserted_at + interval '7 days') as has_instructions_d7,
  max(extract(epoch from (tk.updated_at - o.inserted_at))/86400) filter (where tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days' and tk.updated_at >= o.inserted_at) as last_done_day_d7,
  min(extract(epoch from (tk.updated_at - o.inserted_at))/86400) filter (where tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '7 days' and tk.updated_at >= o.inserted_at) as first_done_day_d7,
  count(*) filter (where tk.status::text = 'completed' and tk.updated_at > o.inserted_at + interval '4 days' and tk.updated_at <= o.inserted_at + interval '7 days') as done_last3_d7,
  count(*) filter (where tk.type = 'employee_data_completion' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_employee_data_completion_d14,
  count(*) filter (where tk.type = 'employee_data_completion' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_employee_data_completion_d14,
  count(*) filter (where tk.type = 'employee_document_completion' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_employee_document_completion_d14,
  count(*) filter (where tk.type = 'employee_document_completion' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_employee_document_completion_d14,
  count(*) filter (where tk.type = 'employee_contract_sign' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_employee_contract_sign_d14,
  count(*) filter (where tk.type = 'employee_contract_sign' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_employee_contract_sign_d14,
  count(*) filter (where tk.type = 'deposit_invoice' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_deposit_invoice_d14,
  count(*) filter (where tk.type = 'deposit_invoice' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_deposit_invoice_d14,
  count(*) filter (where tk.type = 'payment_verification' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_payment_verification_d14,
  count(*) filter (where tk.type = 'payment_verification' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_payment_verification_d14,
  count(*) filter (where tk.type = 'form' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_form_d14,
  count(*) filter (where tk.type = 'form' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_form_d14,
  count(*) filter (where tk.type = 'worker_management_team' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_worker_management_team_d14,
  count(*) filter (where tk.type = 'worker_management_team' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_worker_management_team_d14,
  count(*) filter (where tk.type = 'associate_employee_documents' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_associate_employee_documents_d14,
  count(*) filter (where tk.type = 'associate_employee_documents' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_associate_employee_documents_d14,
  count(*) filter (where tk.type = 'email_template' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_email_template_d14,
  count(*) filter (where tk.type = 'email_template' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_email_template_d14,
  count(*) filter (where tk.type = 'instructions' and tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days') as done_instructions_d14,
  count(*) filter (where tk.type = 'instructions' and tk.inserted_at <= o.inserted_at + interval '14 days') as has_instructions_d14,
  max(extract(epoch from (tk.updated_at - o.inserted_at))/86400) filter (where tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days' and tk.updated_at >= o.inserted_at) as last_done_day_d14,
  min(extract(epoch from (tk.updated_at - o.inserted_at))/86400) filter (where tk.status::text = 'completed' and tk.updated_at <= o.inserted_at + interval '14 days' and tk.updated_at >= o.inserted_at) as first_done_day_d14,
  count(*) filter (where tk.status::text = 'completed' and tk.updated_at > o.inserted_at + interval '11 days' and tk.updated_at <= o.inserted_at + interval '14 days') as done_last3_d14
from employee_onboardings o join tasks tk on tk.process_id = o.process_id
where o.inserted_at >= '2022-04-01'
group by o.id
